import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceFamily } = loadSpaceGrotesk();



export type CortisolCurveProps = Record<string, any>;

const normalPath =
  "M 0 400 C 50 400, 100 150, 150 150 C 250 150, 350 350, 500 350 C 700 350, 850 450, 1000 450";
const stressedPath =
  "M 0 400 C 50 400, 100 50, 150 50 C 250 50, 350 200, 500 200 C 700 200, 850 300, 1000 300";

const CortisolCurve: React.FC<CortisolCurveProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = false,
  durationInSeconds = 8, // Driven by useVideoConfig in practice
  normalCurveColor = "#10b981",
  stressedCurveColor = "#ef4444",
  axesColor = "#71717a",
  textColor = "#fafafa",
  title = "The Cortisol Curve",
  subtitle = "Natural Rhythm vs. Morning Screen Time",
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  // Dynamic Keyframes based on total duration
  const tAxisIn = 20;
  const tNormalEnd = Math.floor(durationInFrames * 0.35);
  const tPhoneIn = Math.floor(durationInFrames * 0.45);
  const tStressedEnd = Math.floor(durationInFrames * 0.75);
  const tLabelIn = Math.floor(durationInFrames * 0.85);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Title Animations
  const axesOpacity = interpolate(frame, [0, tAxisIn], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleOpacity = interpolate(frame, [0, tAxisIn], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY =
    spring({
      frame,
      fps,
      config: { damping: 12 },
      durationInFrames: tAxisIn,
    }) *
      10 -
    10;

  // Normal Curve Animations
  const normalProgress = interpolate(frame, [tAxisIn, tNormalEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });
  const normalEvolved = evolvePath(normalProgress, normalPath);

  const normalLabelOpacity = interpolate(
    frame,
    [tNormalEnd - 15, tNormalEnd],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Phone Element Animations
  const phoneScale = spring({
    frame: frame - tNormalEnd,
    fps,
    config: { damping: 10, mass: 0.8 },
  });
  const phoneRot = phoneScale * 15 - 15; // Rotates from -15deg to 0deg

  const dotPulse = interpolate(frame, [tPhoneIn, tPhoneIn + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Stressed Curve Animations
  const stressedProgress = interpolate(
    frame,
    [tPhoneIn, tStressedEnd],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    }
  );
  const stressedEvolved = evolvePath(stressedProgress, stressedPath);

  const stressedLabelOpacity = interpolate(
    frame,
    [tStressedEnd, tLabelIn],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        padding: "80px 120px",
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* Header Area */}
      <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
        <h1
          style={{
            fontFamily: spaceFamily,
            margin: 0,
            color: textColor,
            fontSize: 64,
            fontWeight: 700,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
          }}
        >
          {title}
        </h1>
        <h2
          style={{
            fontFamily: interFamily,
            margin: 0,
            color: axesColor,
            fontSize: 32,
            fontWeight: 400,
            opacity: axesOpacity,
          }}
        >
          {subtitle}
        </h2>
      </div>

      {/* Chart Area */}
      <div style={{ flex: 1, marginTop: "60px", position: "relative" }}>
        <svg
          width="100%"
          height="100%"
          viewBox="0 0 1000 500"
          style={{ overflow: "visible" }}
        >
          {/* Background Grid */}
          {[100, 200, 300, 400].map((y) => (
            <line
              key={y}
              x1="0"
              y1={y}
              x2="1000"
              y2={y}
              stroke={axesColor}
              strokeWidth="2"
              strokeDasharray="6 6"
              opacity={0.15 * axesOpacity}
            />
          ))}

          {/* Axes */}
          <line
            x1="0"
            y1="450"
            x2="1000"
            y2="450"
            stroke={axesColor}
            strokeWidth="4"
            opacity={axesOpacity}
            strokeLinecap="round"
          />
          <line
            x1="0"
            y1="50"
            x2="0"
            y2="450"
            stroke={axesColor}
            strokeWidth="4"
            opacity={axesOpacity}
            strokeLinecap="round"
          />

          {/* X-Axis Labels */}
          <text
            x="0"
            y="490"
            fill={axesColor}
            fontSize="24"
            fontFamily={interFamily}
            textAnchor="start"
            opacity={axesOpacity}
          >
            6:00 AM (Waking)
          </text>
          <text
            x="500"
            y="490"
            fill={axesColor}
            fontSize="24"
            fontFamily={interFamily}
            textAnchor="middle"
            opacity={axesOpacity}
          >
            2:00 PM
          </text>
          <text
            x="1000"
            y="490"
            fill={axesColor}
            fontSize="24"
            fontFamily={interFamily}
            textAnchor="end"
            opacity={axesOpacity}
          >
            10:00 PM
          </text>

          {/* Y-Axis Labels */}
          <text
            x="-20"
            y="60"
            fill={axesColor}
            fontSize="24"
            fontFamily={interFamily}
            textAnchor="end"
            opacity={axesOpacity}
          >
            High
          </text>
          <text
            x="-20"
            y="440"
            fill={axesColor}
            fontSize="24"
            fontFamily={interFamily}
            textAnchor="end"
            opacity={axesOpacity}
          >
            Low
          </text>

          {/* Normal Curve */}
          {normalProgress > 0 && (
            <>
              <path
                d={normalPath}
                stroke={normalCurveColor}
                opacity={0.2}
                strokeWidth={12}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                {...normalEvolved}
              />
              <path
                d={normalPath}
                stroke={normalCurveColor}
                strokeWidth={4}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                {...normalEvolved}
              />
            </>
          )}

          {/* Normal Curve Label */}
          <text
            x="700"
            y="320"
            fill={normalCurveColor}
            fontSize="22"
            fontFamily={interFamily}
            fontWeight="bold"
            opacity={normalLabelOpacity}
          >
            Natural Baseline
          </text>
          <line
            x1="700"
            y1="330"
            x2="700"
            y2="345"
            stroke={normalCurveColor}
            strokeWidth="2"
            opacity={normalLabelOpacity}
          />

          {/* Stressed Curve */}
          {stressedProgress > 0 && (
            <>
              <path
                d={stressedPath}
                stroke={stressedCurveColor}
                opacity={0.25}
                strokeWidth={16}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                {...stressedEvolved}
              />
              <path
                d={stressedPath}
                stroke={stressedCurveColor}
                strokeWidth={6}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                {...stressedEvolved}
              />
            </>
          )}

          {/* Stressed Curve Label */}
          <text
            x="400"
            y="120"
            fill={stressedCurveColor}
            fontSize="26"
            fontFamily={interFamily}
            fontWeight="bold"
            textAnchor="middle"
            opacity={stressedLabelOpacity}
          >
            Chronic Elevation
          </text>
          <line
            x1="400"
            y1="130"
            x2="400"
            y2="190"
            stroke={stressedCurveColor}
            strokeWidth="3"
            strokeDasharray="6 6"
            opacity={stressedLabelOpacity}
          />

          {/* Phone Icon Trigger */}
          {phoneScale > 0.01 && (
            <g
              transform={`translate(90, 260) scale(${phoneScale}) rotate(${phoneRot})`}
            >
              {/* Phone Body */}
              <rect
                x="-25"
                y="-45"
                width="50"
                height="90"
                rx="8"
                fill="#18181b"
                stroke={axesColor}
                strokeWidth="3"
              />
              {/* Phone Screen */}
              <rect
                x="-19"
                y="-35"
                width="38"
                height="65"
                rx="3"
                fill="#09090b"
              />
              <circle cx="0" cy="38" r="4" fill={axesColor} />

              {/* Notification Dot */}
              {dotPulse > 0 && dotPulse < 1 && (
                <circle
                  cx="20"
                  cy="-35"
                  r={10 + dotPulse * 15}
                  fill={stressedCurveColor}
                  opacity={1 - dotPulse}
                />
              )}
              <circle
                cx="20"
                cy="-35"
                r="10"
                fill={stressedCurveColor}
              />
            </g>
          )}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default CortisolCurve;